// === ANALYSE GSC + SÉLECTION DU MOT-CLÉ ===

// Handle GSC error gracefully — fallback to keyword list if auth fails
const gscData = $input.item.json?.error ? { rows: [] } : ($input.item.json || { rows: [] });
const today = new Date();
const startOfYear = new Date(today.getFullYear(), 0, 1);
const dayOfYear = Math.floor((today - startOfYear) / 86400000);
const hourOfDay = today.getHours();
const rotationIndex = (dayOfYear * 24 + hourOfDay);

// Liste de secours si GSC a peu de données
const fallbackKeywords = [
