    "intention": "combien de temps dure une succession",
    "category": "Succession"
  },
  {
    "keyword": "héritage sans testament notaire",
    "intention": "que se passe-t-il sans testament",
    "category": "Succession"
  },
  {
    "keyword": "déclaration de succession notaire",
    "intention": "comment faire sa déclaration de succession",
    "category": "Succession"
  },
  {
    "keyword": "frais de notaire vente immobilière",
    "intention": "calculer les frais de notaire pour une vente",
    "category": "Immobilier"
  },
  {
    "keyword": "frais de notaire achat maison",
    "intention": "frais de notaire pour acheter une maison",
    "category": "Immobilier"
  },
  {
    "keyword": "acte de vente notaire immobilier",
    "intention": "signature acte définitif chez le notaire",
    "category": "Immobilier"
  },
  {
    "keyword": "compromis de vente notaire",
    "intention": "signer un compromis chez le notaire",
    "category": "Immobilier"
  },
  {
    "keyword": "frais notaire maison ancienne",
    "intention": "frais de notaire dans l'ancien",
    "category": "Immobilier"
  },
  {
    "keyword": "contrat de mariage notaire",
    "intention": "choisir son contrat de mariage",
    "category": "Mariage"
  },
  {
    "keyword": "notaire PACS mariage différence",
    "intention": "PACS ou mariage chez le notaire",
    "category": "Mariage"
  },
  {
    "keyword": "régime matrimonial notaire",
    "intention": "choisir son régime matrimonial",
    "category": "Mariage"
  },
  {
    "keyword": "donation enfants notaire",
    "intention": "faire une donation à ses enfants de son vivant",
    "category": "Donation"
  },
  {
    "keyword": "donation entre époux notaire",
    "intention": "protéger son conjoint par une donation",
    "category": "Donation"
  },
  {
    "keyword": "rdv notaire rapide",
    "intention": "prendre un rendez-vous notaire rapidement en ligne",
    "category": "Guide"
  },
  {
    "keyword": "prendre rendez-vous notaire en ligne",
    "intention": "réserver un créneau chez un notaire depuis internet",
    "category": "Guide"
  },
  {
    "keyword": "notaire disponible rapidement",
    "intention": "trouver un notaire disponible sous 48h",
    "category": "Guide"
  },
  {
    "keyword": "notaire en ligne rendez-vous visio",
    "intention": "consulter un notaire en vidéo depuis chez soi",
    "category": "Guide"
  },
  {
    "keyword": "premier rendez-vous notaire gratuit",
    "intention": "le 1er RDV notaire est-il payant",
    "category": "FAQ"
  },
  {
    "keyword": "notaire SCI familiale création",
    "intention": "créer une SCI chez le notaire",
    "category": "Immobilier"
  },
  {
    "keyword": "testament notaire coût",
    "intention": "combien coûte un testament chez un notaire",
    "category": "FAQ"
  },
  {
    "keyword": "notaire divorce consentement mutuel",
    "intention": "procédure divorce par acte notarié",
    "category": "Guide"
  }
];

const rows = gscData.rows || [];
let selectedKeyword = null;
let gscContext = '';
let source = 'fallback';

if (rows.length >= 3) {
  const opportunities = rows
    .filter(r => r.position >= 4 && r.position <= 30 && r.impressions >= 2)
    .sort((a, b) => {
      const scoreA = a.impressions * (31 - a.position);
      const scoreB = b.impressions * (31 - b.position);
      return scoreB - scoreA;
    });

  if (opportunities.length > 0) {
    const best = opportunities[rotationIndex % opportunities.length];
    selectedKeyword = {
      keyword: best.keys[0],
      intention: `améliorer le ranking sur "${best.keys[0]}"`,
      category: 'FAQ',
      gsc_position: Math.round(best.position * 10) / 10,
      gsc_impressions: best.impressions,
      gsc_clicks: best.clicks,
      gsc_ctr: Math.round(best.ctr * 1000) / 10,
    };
    source = 'gsc';
    gscContext = `\n\nDonnées GSC réelles :\n- Position actuelle : ${selectedKeyword.gsc_position} → objectif top 3\n- Impressions / 7j : ${selectedKeyword.gsc_impressions}\n- Clics : ${selectedKeyword.gsc_clicks} · CTR : ${selectedKeyword.gsc_ctr}%`;
  }
}

if (!selectedKeyword) {
  const fb = fallbackKeywords[rotationIndex % fallbackKeywords.length];
  selectedKeyword = { ...fb, gsc_position: null, gsc_impressions: 0, gsc_clicks: 0, gsc_ctr: 0 };
}

return [{ json: { ...selectedKeyword, gscContext, source, date: today.toISOString().split('T')[0], dayOfYear } }];

const kw = $input.item.json;

const gscLine = kw.source === 'gsc'
  ? `

📊 DONNÉES GOOGLE SEARCH CONSOLE :
- Position actuelle : ${kw.gsc_position} → objectif top 3
- Impressions (7j) : ${kw.gsc_impressions} · Clics : ${kw.gsc_clicks} · CTR : ${kw.gsc_ctr}%
Ce mot-clé est en striking distance.`
  : '';

const prompt = `Tu es un expert SEO spécialisé en droit notarial français, rédacteur senior pour Notaires.io.

Notaires.io est une plateforme digitale qui permet aux particuliers de trouver le bon notaire en 3 questions et prendre rendez-vous en visio ou au cabinet. 1er RDV offert. 17 000+ notaires référencés.${gscLine}

Génère un article SEO complet en français ciblant :
- Mot-clé principal : ${kw.keyword}
- Intention de recherche : ${kw.intention}
- Catégorie : ${kw.category}

Réponds UNIQUEMENT avec un objet JSON valide (sans markdown ni texte autour) :
{
  "meta_title": "titre <title>, 55-60 car, mot-clé en début",
  "meta_description": "meta desc 140-155 car avec CTA",
  "h1": "titre H1 engageant",
  "slug": "slug-url-kebab-sans-accents",
  "excerpt": "résumé 120-150 mots, mot-clé dans les 50 premiers mots",
  "intro": "intro 80-100 mots",
  "content_html": "article HTML complet avec h2, h3, p, ul/li, strong — 1300 à 1700 mots",
  "faq": [{ "q": "question naturelle", "r": "réponse 60-80 mots" }],
  "category": "Succession|Immobilier|Mariage|Famille|Donation|Guide|FAQ|Local",
  "reading_time": 6
}

Règles : 4-6 sections H2, 3-5 questions FAQ, ton expert accessible, mentionner Notaires.io naturellement.`;

const body = JSON.stringify({
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  messages: [{ role: 'user', content: prompt }]
});

return [{ json: { body, keyword: kw } }];

const response = $input.item.json;
const kw = $('🧠 Construire prompt Claude').item.json.keyword;

let rawText;
try {
  rawText = response.content[0].text;
} catch(e) {
  throw new Error('Réponse Claude illisible: ' + JSON.stringify(response).substring(0, 200));
}

let art;
try {
  const cleaned = rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  art = JSON.parse(cleaned);
} catch(e) {
  throw new Error('JSON invalide: ' + rawText.substring(0, 400));
}

const slug = (art.slug || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9-]/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '');
const now = new Date();
const dateSuffix = now.getFullYear() + '-' + String(now.getMonth()+1).padStart(2,'0') + '-' + String(now.getDate()).padStart(2,'0') + '-' + String(now.getHours()).padStart(2,'0') + 'h';
const uniqueSlug = slug; // horodatage retire : il creait un doublon par execution

const article = {
  slug: uniqueSlug || slug,
  title: art.h1 || art.meta_title || kw.keyword,
  meta_title: art.meta_title || null,
  meta_description: art.meta_description || null,
  excerpt: art.excerpt || null,
  h1: art.h1 || null,
  intro: art.intro || null,
  content_html: art.content_html || '',
  faq_json: art.faq || null,
  category: art.category || kw.category || 'Guide',
  keyword: kw.keyword,
  keyword_type: kw.source || 'fallback',
  reading_time: art.reading_time || 6,
  published: true,
};

return [{ json: { article, keyword: kw } }];

const article = $('🔍 Parser réponse Claude').item.json.article;
const kw = $('🔍 Parser réponse Claude').item.json.keyword;
const date = new Date().toLocaleDateString('fr-FR', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
const url = `https://notaires.io/blog/${article.slug}`;

const gscBadge = kw.source === 'gsc'
  ? `<div style="background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">📊 <strong>GSC</strong> — Position actuelle : <strong>${kw.gsc_position}</strong> · ${kw.gsc_impressions} impressions · ${kw.gsc_ctr}% CTR</div>`
  : `<div style="background:#fef9c3;border:1px solid #fde047;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">📋 Source : liste prédéfinie (données GSC pas encore suffisantes)</div>`;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:-apple-system,sans-serif;max-width:640px;margin:0 auto;padding:20px;background:#fff;color:#1f2937"><div style="background:linear-gradient(135deg,#1c4587,#2d5dbf);color:white;padding:20px 24px;border-radius:12px;margin-bottom:18px"><div style="font-size:12px;opacity:.75;margin-bottom:4px">✅ SEO Agent Notaires.io · ${date}</div><div style="font-size:20px;font-weight:700">Article publié automatiquement</div><div style="font-size:13px;opacity:.9;margin-top:4px">🎯 <strong>${kw.keyword}</strong> · ${article.category}</div></div>${gscBadge}<div style="background:#f0f7ff;border:1px solid #bfdbfe;border-radius:10px;padding:14px 18px;margin-bottom:14px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#2d5dbf;margin-bottom:8px">📌 BALISES SEO</div><div style="margin-bottom:6px"><span style="font-size:11px;color:#6b7280">TITLE (${(article.meta_title||'').length} car)</span><br><strong style="color:#1c4587">${article.meta_title}</strong></div><div style="margin-bottom:6px"><span style="font-size:11px;color:#6b7280">META DESC</span><br>${article.meta_description}</div><div><span style="font-size:11px;color:#6b7280">URL</span><br><a href="${url}" style="color:#2d5dbf;font-family:monospace">${url}</a></div></div><div style="background:#ecfdf5;border:1px solid #6ee7b7;border-radius:10px;padding:14px 18px;margin-bottom:14px;text-align:center"><div style="font-size:15px;font-weight:700;color:#065f46;margin-bottom:8px">🚀 Article en ligne maintenant</div><a href="${url}" style="display:inline-block;background:#059669;color:white;padding:10px 20px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px">Voir l'article →</a></div><div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:14px 18px;margin-bottom:14px"><h3 style="color:#1c4587;margin:0 0 6px;font-size:17px">${article.h1}</h3><p style="color:#374151;font-size:14px;line-height:1.6;margin:0">${article.excerpt||article.intro||''}</p></div><div style="text-align:center;color:#9ca3af;font-size:11px;border-top:1px solid #f3f4f6;padding-top:12px">Agent SEO autonome · <a href="https://notaires.io/blog" style="color:#2d5dbf">notaires.io/blog</a></div></body></html>`;

return [{ json: { subject: `✅ Article publié : "${kw.keyword}" — notaires.io/blog/${article.slug}`, html } }];
